# Lexers and formatters implementation continues

def lex_go(code):
    tokens = []
    pos = 0
    # Simple lexer for Go
    keywords_namespace = {"package", "import"}
    keywords_decl = {"func", "var", "const", "type", "struct", "map", "chan", "interface"}
    while pos < len(code):
        if code[pos] == '\n':
            tokens.append(("TextWhitespace", "\n"))
            pos += 1
            continue
        if code[pos].isspace():
            start = pos
            while pos < len(code) and code[pos].isspace() and code[pos] != '\n':
                pos += 1
            tokens.append(("TextWhitespace", code[start:pos]))
            continue
        if code.startswith("//", pos):
            end = code.find("\n", pos)
            if end == -1:
                end = len(code)
                tokens.append(("CommentSingle", code[pos:end]))
                pos = end
            else:
                tokens.append(("CommentSingle", code[pos:end]))
                pos = end
            continue
        if code[pos] == '"':
            end = pos+1
            while end < len(code):
                if code[end] == '"' and code[end-1] != '\\':
                    end +=1
                    break
                end+=1
            # For Go, strings go as LiteralString
            tokens.append(("LiteralString", code[pos:end]))
            pos=end
            continue
        if code[pos].isalpha() or code[pos]=='_':
            start=pos
            while pos<len(code) and (code[pos].isalnum() or code[pos]=='_'):
                pos+=1
            word=code[start:pos]
            if word in keywords_namespace:
                tokens.append(("KeywordNamespace", word))
            elif word in keywords_decl:
                tokens.append(("KeywordDeclaration", word))
            else:
                # Check if previous declaration was func -> function name
                # need to look back ignoring whitespace
                # Simplified: if previous non-whitespace token was KeywordDeclaration func
                found_func=False
                for t,_ in reversed(tokens):
                    if t=="TextWhitespace":
                        continue
                    if t=="KeywordDeclaration":
                        found_func=True
                    break
                # But we need to know if word after func
                # Check if last KeywordDeclaration is func and we are immediately after
                # For simplicity, if word after func, mark as NameFunction
                if tokens and tokens[-1][0]=="KeywordDeclaration" and tokens[-1][1]=="func":
                    # Peek ahead for '('
                    peek=pos
                    while peek<len(code) and code[peek].isspace():
                        peek+=1
                    if peek < len(code) and code[peek]=='(':
                        tokens.append(("NameFunction", word))
                    else:
                        tokens.append(("NameOther", word))
                elif word=="main":
                    tokens.append(("NameOther", word))
                else:
                    # Determine if it's a keyword like package? Already handled
                    # For hello world with go lexer, "hello" and "world" were "Name" -> but we saw hello world gave Name? Actually hello world with go lexer gave "hello" as n? Let's see earlier: hello world with go lexer friendly gave "hello\x1b[37m \x1b[0mworld" meaning both were not keywords, colored as TextWhitespace? Actually output was "hello\x1b[37m \x1b[0mworld\x1b[37m\x1b[0m" meaning hello and world were not highlighted (maybe NameOther? but with no color? Hard to tell)
                    # For simplicity, treat as Name
                    tokens.append(("Name", word))
            continue
        if code[pos] in "(){}[];,.:":
            start=pos
            while pos<len(code) and code[pos] in "(){}[];,.:":
                pos+=1
            tokens.append(("Punctuation", code[start:pos]))
            continue
        if code[pos].isdigit():
            start=pos
            while pos<len(code) and (code[pos].isdigit() or code[pos] in ".xXa-fA-F"):
                pos+=1
            tokens.append(("LiteralNumberInteger", code[start:pos]))
            continue
        # fallback single char
        # Handle operators
        if code[pos] in "=+-*/%<>!&|^~":
            tokens.append(("Operator", code[pos]))
            pos+=1
            continue
        tokens.append(("Text", code[pos]))
        pos+=1
    return tokens

def lex_python(code):
    tokens=[]
    pos=0
    keywords={"def","pass","import","from","class","if","else","elif","for","while","return","and","or","not","in","is","None","True","False","as"}
    builtins={"print","range","len","open"}
    while pos < len(code):
        ch=code[pos]
        if ch=='\n':
            tokens.append(("Text", "\n"))
            pos+=1
            continue
        if ch in " \t":
            start=pos
            while pos<len(code) and code[pos] in " \t":
                pos+=1
            tokens.append(("Text", code[start:pos]))
            continue
        if ch=='#':
            end=code.find("\n",pos)
            if end==-1:
                end=len(code)
            tokens.append(("CommentSingle", code[pos:end]))
            pos=end
            continue
        if ch=='"' or ch=="'":
            q=ch
            if code.startswith(q*3, pos):
                end=code.find(q*3, pos+3)
                if end==-1:
                    end=len(code)
                else:
                    end+=3
                tokens.append(("LiteralStringDouble", code[pos:end]))
                pos=end
                continue
            else:
                end=pos+1
                while end < len(code):
                    if code[end]==q and code[end-1]!='\\':
                        end+=1
                        break
                    end+=1
                tokens.append(("LiteralStringDouble", code[pos:end]))
                pos=end
                continue
        if ch.isalpha() or ch=='_':
            start=pos
            while pos<len(code) and (code[pos].isalnum() or code[pos]=='_'):
                pos+=1
            word=code[start:pos]
            if word in builtins:
                tokens.append(("NameBuiltin", word))
            elif word in keywords:
                tokens.append(("Keyword", word))
            else:
                # check if previous was def
                if tokens and len(tokens)>=1:
                    # find previous non-text
                    prev=None
                    for t,v in reversed(tokens):
                        if t!="Text":
                            prev=t
                            prev_v=v
                            break
                        else:
                            if v.strip()!="":
                                break
                            continue
                    if prev=="Keyword" and prev_v=="def":
                        tokens.append(("NameFunction", word))
                    else:
                        tokens.append(("Name", word))
                else:
                    tokens.append(("Name", word))
            continue
        if ch in "()[]{}:,.":
            # Group consecutive punctuation like "():"
            start=pos
            pos+=1
            while pos<len(code) and code[pos] in "()[]{}:,.":
                pos+=1
            tokens.append(("Punctuation", code[start:pos]))
            continue
        if ch.isdigit():
            start=pos
            while pos<len(code) and code[pos].isdigit():
                pos+=1
            tokens.append(("LiteralNumberInteger", code[start:pos]))
            continue
        if ch in "=+-*/%<>!&|^~":
            tokens.append(("Operator", ch))
            pos+=1
            continue
        tokens.append(("Text", ch))
        pos+=1
    return tokens

def lex_plaintext(code):
    # Simple: each word as Name? For go hello world we saw hello and world as n? Actually plaintext should give just Text?
    # For python hello world gave plain no highlighting
    # For go hello world with go lexer gave hello world with minimal highlighting (maybe as Name)
    # For plaintext fallback we produce single Text token
    # But for lex_plaintext used when lexer is plaintext, we produce one token per line?
    # Let's produce a single Text token for whole code
    # However earlier with python lexer, "hello world" gave no highlighting (plain). With plaintext, same.
    # So we can just return [("Text", code)]
    return [("Text", code)] if code else []

def lex_fallback(code):
    return [("Text", code)] if code else []

def get_style_status(style_name):
