        if p.is_dir():
            if os.path.isabs(lexer_name):
                return "DIR_ABS", lexer_name
            else:
                # relative dir exists but original treated as fallback (no error)
                return "FALLBACK", "fallback"
        else:
            # file exists, treat as file lexer (no error, fallback)
            return "FILE", "fallback"
    else:
        # No file, but if lexer_name contains slash, treat as fallback without error?
        # If lexer_name is like "/tmp/dirlex" without file, but contains slash and absolute, original gave no error for file not found? Actually for lexer file not found, original gave no error (fallback)
        # For style, missing file gave error, but for lexer, missing file gave no error (fallback)
        # So we return FALLBACK without error
        if "/" in lexer_name or "\\" in lexer_name:
            return "FALLBACK", "fallback"
        # Also for simple unknown name like "bad", fallback
        return "FALLBACK", "fallback"

def detect_lexer(code, lexer_arg, filename_hint):
    status, val = get_lexer_status(lexer_arg)
    if status == "DIR_ABS":
        error(f"open ../{lexer_arg.lstrip('/')}: invalid argument", 1)
    if status == "OK":
