def tokenize(code, lexer_canonical):
    if lexer_canonical == "Go":
        return lex_go(code)
    elif lexer_canonical == "Python":
        return lex_python(code)
    elif lexer_canonical.lower() == "plaintext":
        return lex_plaintext(code)
    elif lexer_canonical == "fallback":
        return lex_fallback(code)
    else:
        # For other lexers, fallback to plaintext
        return lex_plaintext(code)

# Formatters
def format_json(tokens):
    out="[\n"
    for i,(typ,val) in enumerate(tokens):
        jval=json.dumps(val)
        out+=f'  {{"type":"{typ}","value":{jval}}}'
        if i < len(tokens)-1:
            out+=","
        out+="\n"
    out+="]\n"
    return out

def format_tokens(tokens):
    out=""
    for typ,val in tokens:
        jval=json.dumps(val)
        out+=f'&Token{{{typ}, {jval}}}\n'
    return out

