# --- Lexers ---
def lex_go(code):
    tokens=[]
    pos=0
    kw_ns={"package","import"}
    kw_decl={"func","var","const","type","struct","map","chan","interface"}
    while pos<len(code):
        if code[pos]=='\n':
            tokens.append(("TextWhitespace","\n"))
            pos+=1
            continue
        if code[pos].isspace():
            start=pos
            while pos<len(code) and code[pos].isspace() and code[pos]!='\n':
                pos+=1
            tokens.append(("TextWhitespace",code[start:pos]))
            continue
        if code.startswith("//",pos):
            end=code.find("\n",pos)
            if end==-1:
                end=len(code)
            tokens.append(("CommentSingle",code[pos:end]))
            pos=end
            continue
        if code[pos]=='"':
            end=pos+1
            while end<len(code):
                if code[end]=='"' and code[end-1]!='\\':
                    end+=1
                    break
                end+=1
            tokens.append(("LiteralString",code[pos:end]))
            pos=end
            continue
        if code[pos].isalpha() or code[pos]=='_':
            start=pos
            while pos<len(code) and (code[pos].isalnum() or code[pos]=='_'):
                pos+=1
            w=code[start:pos]
            if w in kw_ns:
                tokens.append(("KeywordNamespace",w))
            elif w in kw_decl:
                tokens.append(("KeywordDeclaration",w))
            else:
                if tokens and tokens[-1][0]=="KeywordDeclaration" and tokens[-1][1]=="func":
                    peek=pos
                    while peek<len(code) and code[peek].isspace():
                        peek+=1
                    if peek<len(code) and code[peek]=='(':
                        tokens.append(("NameFunction",w))
                    else:
                        tokens.append(("NameOther",w))
                elif w=="main":
                    tokens.append(("NameOther",w))
                else:
                    tokens.append(("Name",w))
            continue
        if code[pos] in "(){}[];,.:":
            start=pos
            while pos<len(code) and code[pos] in "(){}[];,.:":
                pos+=1
            tokens.append(("Punctuation",code[start:pos]))
            continue
        if code[pos].isdigit():
            start=pos
            while pos<len(code) and (code[pos].isdigit() or code[pos] in ".xXa-fA-F"):
                pos+=1
            tokens.append(("LiteralNumberInteger",code[start:pos]))
            continue
        if code[pos] in "=+-*/%<>!&|^~":
            tokens.append(("Operator",code[pos]))
            pos+=1
            continue
        tokens.append(("Text",code[pos]))
        pos+=1
    return tokens

def lex_python(code):
    tokens=[]
    pos=0
    kw={"def","pass","import","from","class","if","else","elif","for","while","return","and","or","not","in","is","None","True","False","as"}
    bi={"print","range","len","open"}
    while pos<len(code):
        ch=code[pos]
        if ch=='\n':
            tokens.append(("Text","\n"))
            pos+=1
            continue
        if ch in " \t":
            start=pos
            while pos<len(code) and code[pos] in " \t":
                pos+=1
            tokens.append(("Text",code[start:pos]))
            continue
        if ch=='#':
            end=code.find("\n",pos)
            if end==-1:
                end=len(code)
            tokens.append(("CommentSingle",code[pos:end]))
            pos=end
            continue
        if ch=='"' or ch=="'":
            q=ch
            if code.startswith(q*3,pos):
                end=code.find(q*3,pos+3)
                if end==-1:
                    end=len(code)
                else:
                    end+=3
                tokens.append(("LiteralStringDouble",code[pos:end]))
                pos=end
                continue
            else:
                end=pos+1
                while end<len(code):
                    if code[end]==q and code[end-1]!='\\':
                        end+=1
                        break
                    end+=1
                tokens.append(("LiteralStringDouble",code[pos:end]))
                pos=end
                continue
        if ch.isalpha() or ch=='_':
            start=pos
            while pos<len(code) and (code[pos].isalnum() or code[pos]=='_'):
                pos+=1
            w=code[start:pos]
            if w in bi:
                tokens.append(("NameBuiltin",w))
            elif w in kw:
                tokens.append(("Keyword",w))
            else:
                prev=None
                prev_v=None
                for t,v in reversed(tokens):
                    if t!="Text":
                        prev=t
                        prev_v=v
                        break
                    if v.strip()!="":
                        break
                if prev=="Keyword" and prev_v=="def":
                    tokens.append(("NameFunction",w))
                else:
                    tokens.append(("Name",w))
            continue
        if ch in "()[]{}:,.":
            start=pos
            pos+=1
            while pos<len(code) and code[pos] in "()[]{}:,.":
                pos+=1
            tokens.append(("Punctuation",code[start:pos]))
            continue
        if ch.isdigit():
            start=pos
            while pos<len(code) and code[pos].isdigit():
                pos+=1
            tokens.append(("LiteralNumberInteger",code[start:pos]))
            continue
        if ch in "=+-*/%<>!&|^~":
            tokens.append(("Operator",ch))
            pos+=1
            continue
        tokens.append(("Text",ch))
        pos+=1
    return tokens

def lex_plaintext(code):
    return [("Text",code)] if code else []
def lex_fallback(code):
    return [("Text",code)] if code else []

def get_style_status(s):
