                try:
                    txt=p.read_text()
                    if not txt.strip():
                        return "EOF","EOF"
                    if "name=" not in txt:
                        return "MISSING_NAME","missing style name attribute"
                    return "OK",s
                except:
                    return "EOF","EOF"
        return "MISSING", f"open {s}: no such file or directory"
    if s in STYLES_VALID:
        return "OK",s
    p=pathlib.Path(s)
    if p.exists():
        if p.is_dir():
            if os.path.isabs(s):
                return "IS_DIR", f"read {s}: is a directory"
            else:
                return "MISSING", f"open {s}: no such file or directory"
        else:
            try:
                txt=p.read_text(encoding='utf-8',errors='ignore')
