                return "EOF","EOF"
    else:
        return "MISSING", f"open {s}: no such file or directory"

def get_lexer_status(name):
    if name is None or name.lower()=="autodetect":
        return "AUTODETECT",name
    lower=name.lower()
    if lower in ALIASES:
        return "OK", ALIASES[lower]
    p=pathlib.Path(name)
    if p.exists():
        if p.is_dir():
            if os.path.isabs(name):
                return "DIR_ABS",name
            else:
                return "FALLBACK","fallback"
        else:
            return "FILE","fallback"
    else:
        if "/" in name or "\\" in name:
            return "FALLBACK","fallback"
        return "FALLBACK","fallback"

def detect_lexer(code, lexer_arg, filename_hint):
    status,val=get_lexer_status(lexer_arg)
    if status=="DIR_ABS":
        error(f"open ../{lexer_arg.lstrip('/')}: invalid argument",1)
    if status=="OK":
        return val, False
    if status in ("FILE","FALLBACK"):
        return "fallback", True
    if status=="AUTODETECT":
        if filename_hint:
            base=os.path.basename(filename_hint)
            ext=os.path.splitext(filename_hint)[1].lower()
            if base.lower() in ["dockerfile","containerfile","makefile","caddyfile"]:
                low=base.lower()
                if low=="dockerfile":
                    return "Docker",False
                if low=="makefile":
                    return "Makefile",False
                return low,False
            if ext in FILENAME_MAP:
                lex=FILENAME_MAP[ext]
                low=lex.lower()
                if low in ALIASES:
                    return ALIASES[low],False
                return lex,False
        stripped=code.lstrip()
        if stripped.startswith("package "):
            return "Go",False
        if "package " in code and ("func " in code or "import " in code):
            return "Go",False
        if stripped.startswith("func ") or ("func " in code and "{" in code):
            if "def " in code and ":" in code:
                pass
            else:
                return "Go",False
        if code.startswith("#!/usr/bin/env python") or code.startswith("#!/usr/bin/python"):
            return "Python",False
        if "def " in code or "print(" in code:
            if "def " in code or "print(" in code:
                return "Python",False
        return "fallback", True
    return "fallback", True

def tokenize(code, lex):
    if lex=="Go":
        return lex_go(code)
    elif lex=="Python":
        return lex_python(code)
    elif lex.lower()=="plaintext":
        return lex_plaintext(code)
    elif lex=="fallback":
        return lex_fallback(code)
    else:
        return lex_plaintext(code)

def format_json(tokens):
    out="[\n"
    for i,(t,v) in enumerate(tokens):
        j=json.dumps(v)
        out+=f'  {{"type":"{t}","value":{j}}}'
        if i < len(tokens)-1:
            out+=","
        out+="\n"
    out+="]\n"
    return out

def format_tokens(tokens):
    out=""
    for t,v in tokens:
        j=json.dumps(v)
        out+=f'&Token{{{t}, {j}}}\n'
    return out

