        m=m16m.get(style,m16m["friendly"])
        return m.get(t, m.get("TextWhitespace",""))
    if fmt=="terminal16":
        return ansi_for(t,style,"terminal256")
    return ""

def format_terminal(tokens, style, fmt):
    out=""
    for t,v in tokens:
        ansi=ansi_for(t,style,fmt)
        if ansi:
            if v=="\n":
                out+=ansi+"\x1b[0m"+v
            else:
                out+=ansi+v+"\x1b[0m"
        else:
            out+=v
    return out

